# r42 (Gift 20 ส.ค. 2026) — เคสจริง คุณ Areerat เพจ Intake:
# "ลูกค้าสนใจห้องขนาดประมาณกี่ตารางเมตร และงบประมาณหยาบๆ เท่าไหร่ครับ"
# "หยาบ" ในภาษาไทยอ่านว่าไม่สุภาพ ที่ถูกคือ "คร่าวๆ"
# ใช้ regex ไม่ใช่ replace ต่อกัน เพราะ "แบบหยาบ ๆ" ถ้าแทนทีละคู่จะเหลือ "ๆ" ค้าง
_ROUGH_RE = re.compile(r"(?:(?:อย่าง|แบบ|โดย)\s*หยาบ\s*ๆ?|หยาบ\s*ๆ)")


def _fix_tone(t: str) -> str:
    """เกลาโทนภาษาโฆษณา/คำที่ฟังไม่สุภาพ ก่อนส่งออกทุกครั้ง"""
    s = t or ""
    for a, b in _TONE_FIX:
        s = s.replace(a, b)
    return _ROUGH_RE.sub("คร่าวๆ", s)
