# r47 — ประโยคที่ "บอกชัดว่าไม่มีผู้กู้ร่วม" ต้องฟังทุกจังหวะ ไม่ใช่เฉพาะตอนถาม
# เคสจริง Ali Ch'a: ลูกค้าพิมพ์ "ไม่มีคนกู้ร่วมค่ะ" หลังบอทเก็บคำตอบไปแล้ว
# ประโยคนี้เลยตกพื้น บอทยังเข้าใจว่ามีผู้กู้ร่วม แล้วเดินหน้าถามต่อจนขอเบอร์
# ต้องแคบกว่า _NO_COB_HINTS เพราะอันนั้นมีแค่คำว่า "ไม่มี" ใช้นอกบริบทไม่ได้
_NO_COB_SAYS = ("ไม่มีคนกู้ร่วม", "ไม่มีผู้กู้ร่วม", "ไม่มีใครกู้ร่วม",
                "ไม่มีคนกู้ด้วย", "ไม่มีใครกู้ด้วย", "ไม่มีคนกู้",
                "ไม่ได้กู้ร่วม", "ไม่อยากกู้ร่วม", "หาคนกู้ร่วมไม่ได้",
                "กู้คนเดียว", "ยื่นคนเดียว", "กู้เดี่ยว",
                "ไม่ร่วมด้วย", "ไม่ยอมกู้ร่วม", "ไม่สะดวกกู้ร่วม")


def _says_no_coborrower(msg: str) -> bool:
    return _has_any(msg, _NO_COB_SAYS)


def _self_emp_below_bar(data: dict, state: dict) -> bool:
    """อาชีพอิสระที่ยังไม่ถึงเกณฑ์กลางของธนาคาร (2 ปี+ และมีภาษี/จดทะเบียน)"""
    if not state.get("self_employed") or data.get("cash"):
        return False
    yrs = data.get("self_emp_years")
    if yrs is None or yrs >= FREELANCE_MIN_YEARS:
        return False              # ยังไม่รู้อายุงาน = ห้ามฟันธง ต้องถามก่อน
    return not (data.get("biz_registered") or data.get("self_emp_tax") is True)


def _hard_reject(data: dict, state: dict) -> str | None:
    """r47 (Gift เคาะ 20 ส.ค. 2026) — เคสที่ธนาคารไม่รับแน่ๆ ปิดสุภาพ ไม่ขอเบอร์

    Gift เลือกทางนี้เอง: "ปิดสุภาพ ไม่ขอเบอร์เลย"
    เหตุผล — เก็บเบอร์เคสที่ไม่ผ่าน = เซลเสียเวลาโทร และลูกค้าถูกทำให้หวัง
    ก่อนโดนปฏิเสธทีหลัง ซึ่งแย่กว่าบอกตรงๆ ตั้งแต่ในแชท

    ยิงเฉพาะตอนที่ "รู้ครบพอจะฟันธง" เท่านั้น — ต้องบอกแล้วว่าไม่มีผู้กู้ร่วม
    เพราะผู้กู้ร่วมพลิกเคสได้ ปิดก่อนถาม = ตัดเคสดีทิ้งฟรีๆ
    """
    if data.get("cash") or data.get("contact"):
        return None
    if not data.get("co_borrower_none"):
        return None
    if _self_emp_below_bar(data, state):
        return SELF_EMP_SOFT_CLOSE
    if data.get("income_unbankable"):
        # กันปิดผิดคน — ถ้ามีตัวเลขรายได้ของตัวเองถึงเกณฑ์แล้ว ให้คนตรวจต่อ
        _n = data.get("income_baht") or 0
        if _n < LOW_INCOME_BAHT:
            return NO_COBORROWER_CLOSE
    return None


def _parse_income(msg: str) -> int | None:
    """คืนรายได้ต่อเดือนเป็นบาท — อ่านไม่ออกคืน None (ห้ามเดา)"""
    m = (msg or "").replace(",", "").replace(" ", "").lower()
    # "2หมื่น" "18k" "3แสน"
    mt = re.search(r"(\d+(?:\.\d+)?)(พัน|หมื่น|แสน|ล้าน|k)", m)
    if mt:
        return int(float(mt.group(1)) * _UNIT_MULT[mt.group(2)])
    # "สองหมื่น" "สามหมื่นกว่า"
    for w, v in _THAI_DIGIT_WORDS.items():
        for unit, mult in _UNIT_MULT.items():
            if unit != "k" and (w + unit) in m:
                return v * mult
    mt = re.search(r"\d{4,7}", m)
    if mt:
        return int(mt.group(0))
    return None

# ----------------------------------------------------------------------
# Phase 5.9 — เกรดลีดตามกำลังกู้จริง (Gift เคาะ 16 ส.ค. 2026)
# ----------------------------------------------------------------------
#   A = กู้ได้เลย ไม่ต้องปิดภาระ
#   B = ปิดหนี้ก่อน แล้วกู้ได้ 1 ห้อง  (= เคสบริดจ์ งานหลักของ WEC)
#   C = DSR ไม่เกิน 100%
#   D = DSR เกิน 100%  -> เก็บชีตปกติ แต่ "ไม่นัดโทร"
#
# ตัวเลขทั้งหมดยกมาจาก Calculate from Document/_engine/rules.json (bank-loan-rules v2.6)
# ห้ามตั้งเกณฑ์ใหม่ที่นี่ — ถ้าเรตเปลี่ยน ให้แก้ที่ rules.json แล้วซิงก์มา
UNIT_PRICE_BAHT = 2_300_000          # "ซื้อ 1 ห้อง" = ทรัพย์ถูกสุดในลิสต์ (KB)
_LOAN_TERM_YEARS = "30"              # บอทไม่ถามอายุ -> สมมุติ 30 ปี
# ----------------------------------------------------------------------
# วงเงินประมาณการ — โหมด A แบบหลวมๆ (Gift สั่ง 19 ส.ค. 2026 "ใช้ Mode A หลวมๆ")
# ----------------------------------------------------------------------
# ตัวเลขทั้งหมดยกมาจาก _engine/rules.json (bank-loan-rules v2.6) แหล่งเดียวกับ
# เครื่องคำนวณเคสจริง — ที่นี่ตัดรายละเอียดออก (ค่าครองชีพ/กฎ 28 ปี/%นับรายได้
# แยกก้อน) เพราะบอทมีข้อมูลแค่ "รายได้รวม" กับ "ยอดผ่อนรวม" เท่านั้น
# ใช้จัดลำดับลีดอย่างเดียว **ห้ามบอกตัวเลขนี้กับลูกค้า**
#
# ของเดิมใช้เรต 30 ปีตายตัวทุกเคส -> ลูกค้าอายุ 62 ได้วงเงินเท่าคนอายุ 30
# ซึ่งผิดจากความจริงมาก (เจอเคสจริง 19 ส.ค. คุณป้าเกษียณได้เกรด B)
_BANK_RATE = {
    "KTB":   {40: 5600, 30: 5900, 25: 6795, 20: 7200, 15: 7800, 10: 11000},
    "GSB":   {40: 5500, 30: 6303, 25: 6600, 20: 6900, 15: 7200, 10: 11000},
    "GHB":   {40: 6000, 30: 6600, 25: 6900, 20: 7200, 15: 7500},
    "TTB":   {35: 6300, 30: 6500, 25: 7000, 20: 7500, 15: 8000, 10: 11000},
}
# เพดานอายุ (อายุ + ปีกู้ ต้องไม่เกินค่านี้) — rules.json §3.6
_BANK_AGE_CAP = {"KTB": 70, "GSB": 70, "GHB": 70, "TTB": 65}
_TERM_STEPS = [40, 35, 30, 25, 20, 15, 10]
DEFAULT_AGE = 35            # ไม่รู้อายุ -> ใช้ค่ากลางวัยทำงาน (ได้ปีกู้เต็ม)

_BANK_DSR_TIERS = {
    "KTB": [(0, 60), (30000, 70), (100000, 80)],
    "GSB": [(0, 60), (30000, 70), (100000, 80)],
    "GHB": [(0, 50), (30000, 50)],       # ไม่มีสวัสดิการ = 50%
    "TTB": [(30000, 70), (80000, 80)],   # รายได้ <30,000 TTB ไม่รับ
}


def _dsr_for(bank: str, income: int) -> int | None:
    tiers = _BANK_DSR_TIERS.get(bank) or []
    dsr = None
    for min_income, pct in tiers:
        if income >= min_income:
            dsr = pct
    return dsr


def _term_rate(bank: str, age: int):
    """ปีกู้ + ค่างวดต่อล้าน ของแบงก์นั้นที่อายุนี้ — คืน (None, None) ถ้าไม่รับ"""
    cap = _BANK_AGE_CAP.get(bank)
    rates = _BANK_RATE.get(bank) or {}
    if not cap or not rates:
        return None, None
    room = cap - int(age)
    for step in _TERM_STEPS:
        if step <= room and step in rates:
            return step, rates[step]
    return None, None


def _capacity(income: int, debt_monthly: int, age: int | None = None) -> int:
    """วงเงินกู้ประมาณการ (บาท) — เลือกแบงก์ที่ให้ดีที่สุด

    อายุมีผลตรงๆ: ปีกู้ = เพดานอายุ − อายุ · ปีกู้สั้น = ค่างวด/ล้านสูง = วงเงินหด
    """
    a = DEFAULT_AGE if age is None else int(age)
    best = 0
    for bank in _BANK_RATE:
        dsr = _dsr_for(bank, income)
        if not dsr:
            continue
        yrs, rate = _term_rate(bank, a)
        if not rate:
            continue                      # อายุเกินเพดานแบงก์นี้
        room = income * dsr / 100 - max(0, debt_monthly)
        if room <= 0:
            continue
        best = max(best, int(room / rate * 1_000_000))
    return best


