_TAX_NO_WORDS = ("ไม่ได้เสียภาษี", "ไม่เสียภาษี", "ไม่มีภาษี", "ไม่ได้ยื่นภาษี",
                 "ไม่ได้จด", "ไม่จดทะเบียน", "ไม่มีบริษัท", "ยังไม่จด",
                 "ยังไม่เสียภาษี", "ไม่มีเอกสาร")


def _parse_years(msg: str) -> int | None:
    """อ่าน 'ทำมากี่ปี' จากภาษาคนพิมพ์ — 'ปีกว่า' = 1 ปี, 'ครึ่งปี/เดือน' = 0"""
    m = _collapse_ranges((msg or "").strip())
    if re.search(r"(ไม่ถึงปี|ครึ่งปี|เพิ่งเริ่ม|เพิ่งทำ|เพิ่งเปิด)", m):
        return 0
    y = re.search(r"(\d+)\s*ปี", m)
    if y:
        return int(y.group(1))
    mo = re.search(r"(\d+)\s*เดือน", m)
    if mo:
        return int(mo.group(1)) // 12
    # r47 — "ได้ 20 วัน" ต้องอ่านเป็น 0 ปี (เคสจริง Ali Ch'a)
    # ของเดิมไม่มีสาขานี้ เลยตกไปถึง fallback เลขลอยข้างล่าง แล้วอ่าน "20" เป็น
    # "20 ปี" = อายุงาน 20 วัน กลายเป็นผ่านเกณฑ์ 2 ปีแบบสบายๆ
    if re.search(r"\d+\s*(วัน|อาทิตย์|สัปดาห์)", m):
        return 0
    n = re.search(r"(?<!\d)(\d{1,2})(?!\d)", m)
    if n and int(n.group(1)) <= 60:
        return int(n.group(1))
    return None


# r47 — อายุงานที่ลูกค้า "บอกมาเอง" โดยที่บอทยังไม่ได้ถาม (Gift 20 ส.ค. 2026)
# ต่างจาก _parse_years ตรงที่ต้องมีคำบอกอายุงานจริงๆ ถึงจะยอมอ่าน
# ไม่งั้นประโยคอย่าง "รายได้ 13000" จะถูกอ่านเป็น "ทำมา 13000 ปี"
_TENURE_MARKS = ("เพิ่งเริ่ม", "เพิ่งทำ", "เพิ่งเปิด", "เพิ่งขาย", "เริ่มทำ",
                 "ทำมา", "ทำได้", "ทำอาชีพนี้มา", "เปิดร้านมา", "ขายมา",
                 "รับงานมา", "ทำงานนี้มา", "เข้าปีที่")


def _tenure_years(msg: str) -> int | None:
    m = _norm_th(msg)
    if not any(_norm_th(w) in m for w in _TENURE_MARKS):
        return None
    return _parse_years(msg)


def _parse_tax_flag(msg: str) -> bool | None:
    """มีภาษี/จดบริษัทไหม -> True / False / None (ยังไม่รู้)"""
    m = _norm_th(msg)
    # r46 — "จดทะเบียนสมรส" ไม่ใช่เอกสารธุรกิจ ตัดออกก่อนเช็ค
    _biz = _strip_marriage(msg)
    if _has_any(_biz, _TAX_NO_WORDS):
        return False
    if _has_any(_biz, _TAX_YES_WORDS):
        return True
    if re.fullmatch(r"(ไม่|ไม่มี|ยังไม่มี|ยังไม่|ไม่ครับ|ไม่ค่ะ)[ครับค่ะคะจ้า]*", m):
        return False
    if re.fullmatch(r"(มี|มีครับ|มีค่ะ|ใช่|ใช่ครับ|ใช่ค่ะ|เสีย|เสียครับ|เสียค่ะ)[ครับค่ะคะจ้า]*", m):
        return True
    return None



