def _income_known(data: dict) -> bool:
    """r61 (Gift 21 ส.ค. 2026) — ถือว่า "รู้รายได้แล้ว" เมื่อ
       · ได้คำตอบเรื่องรายได้มาแล้ว (ตัวเลขหรือโน้ต)  หรือ
       · ลูกค้าบอกเองว่าไม่สะดวกบอก / ไม่มีรายได้ประจำ (income_unknown)  หรือ
       · ซื้อเงินสด ไม่ได้กู้ (cash) — ไม่มีเหตุผลต้องรู้รายได้

    ใช้เป็นด่านเดียวกันทั้งตอนเลือกคำถามและตอนจะขอเบอร์
    """
    return bool(data.get("income")
                or data.get("income_unknown")
                or data.get("cash"))

# ปฏิเสธชัดเจน -> หยุดถามทันที (กติกาเดียวกับตอนขอเบอร์)
_INCOME_REFUSE_WORDS = (
    "ไม่สะดวกบอก", "ขอไม่บอก", "ไม่อยากบอก", "ไม่ขอบอก", "ไม่บอก",
    "เป็นความลับ", "ส่วนตัว", "ยังไม่บอก", "ไม่สะดวก",
)


def _refuses_income(msg: str) -> bool:
    m = (msg or "").replace(" ", "")
    return any(w.replace(" ", "") in m for w in _INCOME_REFUSE_WORDS)

# ----------------------------------------------------------------------
# เวลาโทรกลับ — Gift เคาะ 16 ส.ค. 2026 : คุยได้ 09:00-20:00 น.
# เลยเวลา -> นัดวันถัดไป ห้ามสัญญาว่าจะโทรตอนดึก
# ----------------------------------------------------------------------
CALL_START_HOUR, CALL_START_MIN = 9, 30     # เริ่มโทรได้ 09:30
CALL_END_HOUR = 20                          # หยุดโทร 20:00
CALL_START_TXT = f"{CALL_START_HOUR:02d}.{CALL_START_MIN:02d}"
CALL_WINDOW_TXT = f"{CALL_START_TXT}-{CALL_END_HOUR:02d}.00 น."
_BKK_TZ = timezone(timedelta(hours=7))


def _bkk_now():
    """เวลาไทยเสมอ — Railway รันเป็น UTC ถ้าไม่ตรึงจะเพี้ยน 7 ชั่วโมง"""
    return datetime.now(_BKK_TZ)


def _call_window(now=None) -> str:
    """'in' = โทรได้ · 'early' = ยังไม่ถึง 09:30 · 'late' = เลย 20:00"""
    t = now or _bkk_now()
    if (t.hour, t.minute) < (CALL_START_HOUR, CALL_START_MIN):
        return "early"
    if t.hour >= CALL_END_HOUR:
        return "late"
    return "in"


# ยอดที่ "เกินจริงสำหรับค่างวดต่อเดือน" = น่าจะเป็นยอดคงเหลือ ไม่ใช่ค่างวด
_DEBT_MAX_MONTHLY = 200_000
_NO_DEBT_WORDS = ("ไม่มี", "ไม่ได้ผ่อน", "ปลอดหนี้", "เคลียร์แล้ว", "ปิดหมดแล้ว",
                  "ไม่ติดอะไร", "ไม่เคยกู้", "ว่าง")


def _collapse_ranges(text: str) -> str:
    """ยุบ "ช่วงตัวเลขของยอดเดียว" ให้เป็นค่ากลาง ก่อนเอาไปบวกกัน

    บั๊กที่เจอจริง 18 ส.ค. 2026 (เคส WO FB-20260817-010 — Gift จับได้):
      "ผ่อนแล้วเดือนละประมาณ 25000-30000 คับ" -> เดิมบวกกันได้ 55,000 (ผิด)
      ที่ถูกคือ ~27,500 -> เกรดเพี้ยนจาก A ไป B/D ทันที
    เงื่อนไขกันพลาด: ตัวหลังต้องมากกว่าตัวหน้า และไม่เกิน 5 เท่า
    ("ผ่อนรถ 8,000 บัตร 5,000" ยังบวกกันเหมือนเดิม เพราะไม่ใช่ช่วง)
    """
    def _mid(m):
        a = int(m.group(1).replace(",", ""))
        b = int(m.group(2).replace(",", ""))
        if a < b <= a * 5:
            return str((a + b) // 2)
        return m.group(0)
    return re.sub(r"(\d[\d,]{2,})\s*(?:-|–|—|~|ถึง)\s*(\d[\d,]{2,})", _mid, text or "")


def _parse_debt_monthly(msg: str) -> int | None:
    """อ่าน 'ผ่อนรวมเดือนละเท่าไหร่' จากคำตอบข้อ 3
    คืน 0 = ยืนยันว่าไม่มีภาระ · None = ตอบมาแต่ยังไม่รู้ยอด (เซลต้องถามตอนโทร)

    ระวังกับดัก: ลูกค้ามักพิมพ์ 'ยอดคงเหลือ' ปนมากับค่างวด
    เช่น "เหลืออยู่ 104,053 ผ่อน 8,125/เดือน" -> ต้องได้ 8,125 ไม่ใช่ 112,178
    """
    m = _collapse_ranges((msg or "").strip())
    if not m:
        return None
    low = m.replace(" ", "").lower()
    if any(w in low for w in _NO_DEBT_WORDS) and not re.search(r"\d", low):
        return 0

    def _ok(n: int) -> bool:
        return 300 <= n <= _DEBT_MAX_MONTHLY

    # 1) ตัวเลขที่ "ระบุว่าเป็นต่อเดือน" ชัดเจน -> เชื่อชุดนี้ก่อนเสมอ
    monthly = [int(x.replace(",", "")) for x in re.findall(
        r"(\d[\d,]{2,})\s*(?:บาท)?\s*(?:/|ต่อ\s*)?เดือน", m)]
    monthly += [int(x.replace(",", "")) for x in re.findall(
        r"เดือนละ\s*(?:ประมาณ|ราวๆ|ราว|สัก|~)?\s*(\d[\d,]{2,})", m)]
    monthly = [n for n in monthly if _ok(n)]
    if monthly:
        return sum(monthly)

    # 2) ตัดตัวเลขที่เป็น "ยอดคงเหลือ/ยอดหนี้" ออกก่อน แล้วค่อยรวมที่เหลือ
    cleaned = re.sub(r"(?:คงเหลือ|เหลือ(?:อยู่|ยุ)?|ยอดหนี้|ยอดคงค้าง|ราคา)\s*"
                     r"(?:อีก)?\s*\d[\d,]*", " ", m)
    nums = [int(x.replace(",", "")) for x in re.findall(r"\d[\d,]{2,}", cleaned)]
    nums = [n for n in nums if _ok(n)]
    if nums:
        return sum(nums)

    # 3) "ผ่อนรถ 8 พัน" / "เดือนละ 2 หมื่น"
    n = _parse_income(m)
    if n is not None and _ok(n):
        return n
    return None


_EMOJI_RE = re.compile(
    "[\U0001F000-\U0001FAFF\U00002600-\U000027BF\U0001F1E6-\U0001F1FF⭐✅❌️]+"
)

# ----------------------------------------------------------------------
# Phase 5.8 — กันข้อความ AI ถูกตัดกลางประโยค
# ----------------------------------------------------------------------
# ภาษาไทยกินโทเคนมากกว่าอังกฤษหลายเท่า max_tokens=150 เดิมจึงตัดกลางคำ
# ลูกค้าเห็นข้อความค้างแบบ "...แต่ยังกลัวหรือไม่รู้จะเริ่มอย่างไร เราแน"
# แก้ 2 ชั้น: (1) ขยาย max_tokens  (2) ถ้ายังโดนตัด ถอยไปจบประโยคสมบูรณ์
_SENT_END_RE = re.compile(r"^.*(?:ครับ|ค่ะ|คะ|[.!?])", re.S)
# ทักทาย/แนะนำตัวซ้ำ — ระบบส่ง WELCOME_MSG ไปก่อนแล้ว AI ไม่ต้องทักอีกรอบ
_GREET_RE = re.compile(
    r"^\s*สวัสดี(?:ครับ|ค่ะ|คะ)?\s*[:\-—]?\s*"
    r"(?:(?:wealth\s*estate|อสังหาคุ้มค่า)\s*[:\-—]?\s*){0,3}"
    r"(?:ยินดี\S{0,30}?(?:ครับ|ค่ะ|คะ)\s*)?",
    re.IGNORECASE,
)


def _trim_to_sentence(text: str) -> str:
    """AI ถูกตัดกลางประโยค -> ถอยกลับไปจบที่ประโยคสมบูรณ์ล่าสุด
    ถ้าหาไม่เจอเลย คืนสตริงว่าง ให้ผู้เรียกไปใช้ข้อความสำรองแทน
    (ส่งข้อความสำรอง ดีกว่าส่งประโยคค้างให้ลูกค้าอ่าน)"""
    m = _SENT_END_RE.match(text)
    if m:
        trimmed = m.group(0).strip()
        if len(trimmed) >= 20:
            return trimmed
    return ""


def _strip_dup_greeting(text: str) -> str:
    """ตัดคำทักทายซ้ำหัวข้อความ ถ้าตัดแล้วเหลือสั้นเกินไปให้คงของเดิมไว้"""
    stripped = _GREET_RE.sub("", text, count=1).lstrip(" :-—\n")
    return stripped if len(stripped) >= 15 else text


