def _is_unbankable_job(msg: str) -> bool:
    """อาชีพ/ที่มารายได้ที่ธนาคารไม่รับรอง -> ถือว่าไม่ผ่านเกณฑ์รายได้"""
    m = msg.lower()
    return (any(j in m for j in _UNBANKABLE_JOBS)
            or any(d in m for d in _DEPENDENT_INCOME))


