def _parse_age(msg: str):
    """อ่านอายุจากข้อความ — รับได้ทั้ง '60' '60 ปี' 'อายุ 62' 'หกสิบ'

    กันเลขที่ไม่ใช่อายุ: ปีเกิด (2500+) เงินเดือน (>120) เบอร์โทร
    """
    m = _norm_th(msg)
    for mt in re.finditer(r"(?<!\d)(\d{2})(?!\d)", m):
        n = int(mt.group(1))
        if 18 <= n <= 90:
            return n
    return None


