def _clean_name_token(t: str) -> str:
    t = t.strip(" .,!()\"'“”")
    for p in ("คุณ", "นาย", "นางสาว", "นาง"):
        if t.startswith(p) and len(t) > len(p) + 1:
            t = t[len(p):]
    for _ in range(2):  # "กิ๊กนะครับ" ตัดได้สองชั้น
        for p in ("ครับผม", "ครับ", "ค่ะ", "คะ", "ค่า", "คับ", "จ้า", "จ้ะ",
                  "นะ", "งับ", "ฮะ", "ฮับ", "ค๊ะ"):
            if t.endswith(p) and len(t) > len(p) + 1:
                t = t[: -len(p)]
                break
    return t.strip()


def _looks_like_name(t: str) -> bool:
    """เข้มไว้ก่อน — เก็บชื่อผิดแย่กว่าไม่เก็บ (เซลเรียกชื่อผิด = เสียฟอร์ม)"""
    if not t or not (2 <= len(t) <= 25):
        return False
    if any(ch.isdigit() for ch in t):
        return False
    low = t.lower()
    if any(w in low for w in _NAME_BAD_WORDS):
        return False
    return bool(re.fullmatch(r"[A-Za-zก-๙์ิีึืุูัํ็่้๊๋\s]{2,25}", t))


def _name_from_contact_msg(msg: str) -> str:
    """หาชื่อที่พิมพ์มาพร้อมช่องทาง เช่น "สมชาย 0812345678" / "081... ชื่อกิ๊กครับ"
    เจอชัดเจนเท่านั้นถึงเอา — เดาไม่ได้ให้คืนค่าว่าง (แล้วค่อยถามเอา)"""
    m = str(msg)
    # แบบบอกตรงๆ: "ชื่อ X" / "ผมชื่อ X" / "เรียกว่า X"
    g = re.search(r"ชื่อ(?:เล่น)?\s*(?:ว่า)?\s*([A-Za-zก-๙][A-Za-zก-๙์ิีึืุูัํ็่้๊๋]{1,24})", m)
    if g:
        t = _clean_name_token(g.group(1))
        if _looks_like_name(t):
            return t
    # แบบพิมพ์ปนมา: ตัดเบอร์/ไอดีทิ้ง เหลืออะไรที่เป็นชื่อล้วนๆ ไหม
    rest = re.sub(r"[0-9+\-\s]{6,}", " ", m)          # ตัดกลุ่มตัวเลขเบอร์
    rest = re.sub(r"@?[A-Za-z0-9._-]{4,}", " ", rest)   # ตัด token แบบไอดีไลน์
    toks = [_clean_name_token(w) for w in rest.split()]
    toks = [w for w in toks if w and w not in _NAME_PARTICLES]
    if len(toks) == 1 and _looks_like_name(toks[0]):
        return toks[0]
    return ""


def _name_from_log(state: dict, user_id: str = "") -> str:
    """r52 (Gift 20 ส.ค. 2026) — "ใช้ชื่อจาก log ถ้ามี เพราะถามชื่ออยู่แล้วตอนท้าย"

    เพจ Millionaire Asset โทเค็นดึงชื่อจาก Graph ไม่ได้ (error #3 ต้องรอ Meta
    อนุมัติสิทธิ์แอป) -> ทุกแถวขึ้น "(ยังไม่ได้ชื่อ)" ทั้งที่ในแชทมีชื่ออยู่
    โดยเฉพาะเคสที่เซลรับช่วงคุยเอง เซลมักถามชื่อและลูกค้าตอบไปแล้ว

    เข้มไว้ก่อน — เก็บผิดแย่กว่าไม่เก็บ:
      1. ชื่อที่พิมพ์มาพร้อมเบอร์/ไลน์  ("สมชาย 0812345678")     = แม่นสุด
      2. ประโยคที่มีคำว่า "ชื่อ" ตรงๆ  ("ชื่อนิชาค่ะ")
      3. ข้อความสั้นที่ตอบ "หลังจาก" ฝั่งเราถามหาชื่อ
    """
    def _pick(texts, prev_asked_name):
        for t, asked in zip(texts, prev_asked_name):
            t = (t or "").strip()
            if not t:
                continue
            # r53 — บั๊กที่ผมทำพังใน r52: _name_from_contact_msg ตัดเลข/ไอดีทิ้ง
            # แล้วเอา "อะไรก็ตามที่เหลือ" เป็นชื่อ -> "ทำงานประจำครับ"
            # กลายเป็นชื่อลูกค้าว่า "ทำงานประจำ" (เจอจริงตอนเทสต์เคสพี่บ่าว)
            # ใช้ฟังก์ชันนี้ได้เฉพาะข้อความที่มีเบอร์/ไอดีจริงเท่านั้น
            if _looks_like_phone(t) or len(re.sub(r"\D", "", t)) >= 6:
                nm = _name_from_contact_msg(t)
                if nm:
                    return nm
            # พูดคำว่า "ชื่อ" มาตรงๆ -> จับเฉพาะคำถัดจาก "ชื่อ" คำเดียว
            # ("ชื่อกิ๊กค่ะ สนใจห้องแถวรัชดา" ต้องได้ "กิ๊ก" ไม่ใช่ทั้งประโยค)
            if "ชื่อ" in t:
                g = re.search(r"ชื่อ(?:เล่น)?\s*(?:ว่า)?\s*"
                              r"([A-Za-zก-๙][A-Za-zก-๙์ิีึืุูัํ็่้๊๋]{1,24})", t)
                if g:
                    cand = _clean_name_token(g.group(1))
                    if _looks_like_name(cand):
                        return cand
            # ฝั่งเราเพิ่งถามชื่อไป -> ข้อความถัดมาถือว่าเป็นคำตอบชื่อได้
            if asked:
                nm = _name_from_reply(t)
                if nm:
                    return nm
        return ""

    # ---- ล็อกช่วงเซลรับช่วงคุยเอง ----
    log = state.get("handover_log") or []
    texts, asked = [], []
    _prev_asked = False
    for it in log:
        _t = (it.get("t") or "")
        if it.get("w") == "cust":
            texts.append(_t)
            asked.append(_prev_asked)
            _prev_asked = False
        else:
            _prev_asked = "ชื่อ" in _t
    nm = _pick(texts, asked)
    if nm:
        return nm

    # ---- บทสนทนาที่บอทจำไว้ (RAM/Postgres) ----
    conv = _conversations.get(user_id) or []
    texts, asked = [], []
    _prev_asked = False
    for it in conv:
        _t = (it.get("content") or "")
        if it.get("role") == "user":
            texts.append(_t)
            asked.append(_prev_asked)
            _prev_asked = False
        else:
            _prev_asked = "ชื่อ" in _t
    return _pick(texts, asked)


def _name_from_reply(msg: str) -> str:
    """คำตอบของคำถามขอชื่อ เช่น "กิ๊กครับ" / "ชื่อสมชาย" / "Mild" """
    m = str(msg).strip()
    if len(m) > 40 or "?" in m:
        return ""
    g = re.search(r"ชื่อ(?:เล่น)?\s*(?:ว่า)?\s*(.+)$", m)
    if g:
        m = g.group(1)
    toks = [_clean_name_token(w) for w in m.split()]
    toks = [w for w in toks if w and w not in _NAME_PARTICLES]
    if 1 <= len(toks) <= 2:
        cand = " ".join(toks)
        if _looks_like_name(cand):
            return cand
    return ""



